/* ============================================================
   SND / Gobierno de México inspired theme for R Shiny
   File: www/snd.css

   Main palette:
   Burgundy: #611232
   Dark burgundy: #4a0d25
   Gold: #b38e5d
   Light gray: #f4f4f4
   ============================================================ */

:root {
  --snd-burgundy: #611232;
  --snd-burgundy-dark: #4a0d25;
  --snd-burgundy-light: #7b2848;
  --snd-gold: #b38e5d;
  --snd-gold-light: #d6c19a;
  --snd-gray-100: #f5f5f5;
  --snd-gray-200: #e9e9e9;
  --snd-gray-500: #666666;
  --snd-gray-700: #333333;
  --snd-white: #ffffff;
  --snd-black: #222222;
  --snd-radius: 4px;
  --snd-shadow: 0 2px 8px rgba(0, 0, 0, .10);
}

/* ---------- Base ---------- */

html, body {
  font-family: "Montserrat", "Arial", sans-serif;
  color: var(--snd-gray-700);
  background: #ffffff;
  margin: 0;
  padding: 0;
}

body {
  font-size: 14px;
  line-height: 1.5;
}

h1, h2, h3, h4, h5, h6 {
  font-weight: 600;
  color: var(--snd-burgundy);
}

a {
  color: var(--snd-burgundy);
}

a:hover,
a:focus {
  color: var(--snd-burgundy-dark);
}

/* ---------- Main Shiny container ---------- */

.container-fluid {
  padding-left: 24px;
  padding-right: 24px;
}

/* ---------- Header / title ---------- */

.snd-header {
  background: var(--snd-burgundy);
  color: var(--snd-white);
  padding: 14px 24px;
  border-bottom: 5px solid var(--snd-gold);
  box-shadow: var(--snd-shadow);
}

.snd-header h1,
.snd-header h2,
.snd-header h3 {
  color: var(--snd-white);
  margin: 0;
}

.snd-title {
  color: var(--snd-burgundy);
  font-weight: 700;
  margin-bottom: 20px;
}

/* ---------- Shiny sidebar ---------- */

.well {
  background: var(--snd-gray-100);
  border: 1px solid var(--snd-gray-200);
  border-radius: var(--snd-radius);
  box-shadow: none;
}

.sidebarPanel,
.well {
  color: var(--snd-gray-700);
}

.control-label {
  color: var(--snd-burgundy);
  font-weight: 600;
}

/* ---------- Select inputs ---------- */

.form-control {
  border: 1px solid #bdbdbd;
  border-radius: var(--snd-radius);
  box-shadow: none;
  min-height: 38px;
}

.form-control:focus {
  border-color: var(--snd-burgundy);
  box-shadow: 0 0 0 2px rgba(97, 18, 50, .12);
}

/* ---------- Buttons ---------- */

.btn-primary,
.btn-default.snd-primary {
  background-color: var(--snd-burgundy);
  border-color: var(--snd-burgundy);
  color: var(--snd-white);
  font-weight: 600;
  border-radius: var(--snd-radius);
}

.btn-primary:hover,
.btn-primary:focus,
.btn-default.snd-primary:hover {
  background-color: var(--snd-burgundy-dark);
  border-color: var(--snd-burgundy-dark);
  color: var(--snd-white);
}

.btn-snd-gold {
  background-color: var(--snd-gold);
  border-color: var(--snd-gold);
  color: var(--snd-white);
}

.btn-snd-gold:hover,
.btn-snd-gold:focus {
  background-color: #967546;
  border-color: #967546;
  color: var(--snd-white);
}

/* ---------- Tabs ---------- */

.nav-tabs {
  border-bottom: 3px solid var(--snd-burgundy);
  margin-bottom: 20px;
}

.nav-tabs > li > a {
  color: var(--snd-gray-700);
  font-weight: 600;
  border: none;
  border-radius: 0;
  padding: 12px 20px;
}

.nav-tabs > li > a:hover {
  background: var(--snd-gray-100);
  color: var(--snd-burgundy);
  border: none;
}

.nav-tabs > li.active > a,
.nav-tabs > li.active > a:hover,
.nav-tabs > li.active > a:focus {
  color: var(--snd-white);
  background: var(--snd-burgundy);
  border: 1px solid var(--snd-burgundy);
  border-bottom-color: var(--snd-burgundy);
  font-weight: 700;
}

/* ---------- Panels / cards ---------- */

.snd-card {
  background: var(--snd-white);
  border: 1px solid var(--snd-gray-200);
  border-top: 4px solid var(--snd-burgundy);
  border-radius: var(--snd-radius);
  padding: 20px;
  margin-bottom: 20px;
  box-shadow: var(--snd-shadow);
}

.snd-card-title {
  color: var(--snd-burgundy);
  font-size: 18px;
  font-weight: 700;
  margin-top: 0;
  margin-bottom: 15px;
  border-bottom: 1px solid var(--snd-gray-200);
  padding-bottom: 10px;
}

/* ---------- Plotly containers ---------- */

.plotly.html-widget {
  width: 100% !important;
  background: var(--snd-white);
}

.snd-plot {
  background: var(--snd-white);
  border: 1px solid var(--snd-gray-200);
  border-radius: var(--snd-radius);
  padding: 8px;
  box-shadow: var(--snd-shadow);
  margin-bottom: 20px;
}

/* ---------- DataTables ---------- */

.dataTables_wrapper {
  color: var(--snd-gray-700);
  font-size: 13px;
}

table.dataTable thead th {
  background: var(--snd-burgundy) !important;
  color: var(--snd-white) !important;
  border-bottom: 2px solid var(--snd-gold) !important;
  font-weight: 600;
}

table.dataTable tbody tr:hover {
  background-color: rgba(97, 18, 50, .06) !important;
}

table.dataTable tbody td {
  border-bottom: 1px solid var(--snd-gray-200);
}

.dataTables_wrapper .dataTables_filter input {
  border: 1px solid #bdbdbd;
  border-radius: var(--snd-radius);
  padding: 6px 10px;
}

.dataTables_wrapper .dt-buttons .dt-button {
  background: var(--snd-burgundy) !important;
  color: var(--snd-white) !important;
  border: 1px solid var(--snd-burgundy) !important;
  border-radius: var(--snd-radius) !important;
  margin-right: 5px;
}

.dataTables_wrapper .dt-buttons .dt-button:hover {
  background: var(--snd-burgundy-dark) !important;
}

/* ---------- Value boxes ---------- */

.small-box {
  border-radius: var(--snd-radius);
  box-shadow: var(--snd-shadow);
}

.small-box .icon {
  color: rgba(255, 255, 255, .20);
}

.snd-value-box {
  background: var(--snd-burgundy);
  color: var(--snd-white);
  border-top: 4px solid var(--snd-gold);
  border-radius: var(--snd-radius);
  padding: 18px;
  box-shadow: var(--snd-shadow);
}

.snd-value-box h3,
.snd-value-box p {
  color: var(--snd-white);
}

/* ---------- Alerts ---------- */

.alert-snd {
  background: rgba(97, 18, 50, .07);
  border-left: 5px solid var(--snd-burgundy);
  color: var(--snd-gray-700);
}

/* ---------- Footer ---------- */

.snd-footer {
  background: var(--snd-burgundy);
  color: var(--snd-white);
  border-top: 5px solid var(--snd-gold);
  padding: 20px 24px;
  margin-top: 30px;
  font-size: 12px;
}

.snd-footer a {
  color: var(--snd-gold-light);
}

/* ---------- Logo area ---------- */

.snd-header-logo {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  height: 48px;
  width: auto; 
  max-width: 190px;
  object-fit: contain;
  object-position: center;
  flex: 0 0 auto;
}

/* Gobierno de México */
.snd-header-logo.gobierno {
  height: 46px;
  max-width: 175px;
}

/* Secretaría de Salud */
.snd-header-logo.salud {
  height: 50px;
  max-width: 190px;
}

/* Servicio Nacional de Salud Pública */
.snd-header-logo.snsp {
  height: 54px;
  max-width: 210px;
}

.snd-logo {
  max-height: 70px;
  width: auto;
}

.snd-brand-bar {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 12px 20px;
  background: var(--snd-white);
  border-bottom: 1px solid var(--snd-gray-200);
}

/* ---------- Responsive ---------- */

@media (max-width: 768px) {
  .container-fluid {
    padding-left: 12px;
    padding-right: 12px;
  }

  .nav-tabs > li > a {
    padding: 10px 12px;
    font-size: 13px;
  }

  .snd-header {
    padding: 12px 15px;
  }

  .snd-brand-bar {
    flex-wrap: wrap;
  }
}
